-- ==================================================================================
-- MIGRATION: REVISI KUESIONER STAKEHOLDER MASYARAKAT PESISIR & INDUSTRI
-- Sumber: public/revisi kuesioner/*.docx
-- HANYA memperbarui 84 baris tabel `pertanyaan` (42 masyarakat_pesisir + 42 industri).
-- TIDAK menyentuh tabel `responden` / `jawaban` maupun pertanyaan stakeholder lain.
-- CARA MENJALANKAN: Supabase Dashboard -> SQL Editor -> New Query -> Paste -> Run.
-- ==================================================================================

on conflict (id) do update set
  id_indikator = excluded.id_indikator,
  id_stakeholder_group = excluded.id_stakeholder_group,
  teks_pertanyaan = excluded.teks_pertanyaan,
  skala_label = excluded.skala_label;

notify pgrst, 'reload schema';
