insert into public.pertanyaan (id, id_indikator, id_stakeholder_group, teks_pertanyaan, skala_label) values
  ('Q_IND_01_masyarakat_pesisir', 'IND_01', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu sebagai warga pesisir, bagaimana ketersediaan ikan laut hasil tangkapan nelayan di wilayah Cilegon saat ini dibandingkan dengan beberapa tahun sebelumnya?', '{"1": "Sangat Menurun", "2": "Menurun", "3": "Relatif Tetap", "4": "Meningkat", "5": "Sangat Meningkat"}'::jsonb),
  ('Q_IND_02_masyarakat_pesisir', 'IND_02', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, bagaimana kondisi kebersihan air laut, kebersihan pantai, serta kelestarian habitat pesisir seperti mangrove dan terumbu karang di sekitar wilayah pesisir Cilegon?', '{"1": "Sangat Buruk", "2": "Buruk", "3": "Sedang", "4": "Baik", "5": "Sangat Baik"}'::jsonb),
  ('Q_IND_03_masyarakat_pesisir', 'IND_03', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana kegiatan penangkapan ikan oleh nelayan lokal menimbulkan dampak terhadap kelestarian lingkungan laut, seperti kerusakan habitat laut atau tertangkapnya ikan berukuran kecil?', '{"1": "Dampak Sangat Berat", "2": "Dampak Berat", "3": "Dampak Sedang", "4": "Dampak Ringan", "5": "Dampak Sangat Ringan atau Tidak Ada"}'::jsonb),
  ('Q_IND_04_masyarakat_pesisir', 'IND_04', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana aktivitas industri di sepanjang pesisir Cilegon memengaruhi kualitas lingkungan perairan laut, termasuk potensi pencemaran dan kondisi habitat ikan?', '{"1": "Dampak Sangat Berat", "2": "Dampak Berat", "3": "Dampak Sedang", "4": "Dampak Ringan", "5": "Tidak Ada Dampak Berarti"}'::jsonb),
  ('Q_IND_05_masyarakat_pesisir', 'IND_05', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana usaha perikanan tangkap mampu memberikan pendapatan dan mendukung kesejahteraan keluarga nelayan di wilayah pesisir Kota Cilegon?', '{"1": "Sangat Rendah", "2": "Rendah", "3": "Sedang", "4": "Tinggi", "5": "Sangat Tinggi"}'::jsonb),
  ('Q_IND_06_masyarakat_pesisir', 'IND_06', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana nelayan di lingkungan sekitar dapat memperoleh kebutuhan operasional melaut, seperti BBM, es balok, dan perbekalan, dengan mudah dan harga terjangkau?', '{"1": "Sangat Sulit", "2": "Sulit", "3": "Cukup Mudah", "4": "Mudah", "5": "Sangat Mudah"}'::jsonb),
  ('Q_IND_07_masyarakat_pesisir', 'IND_07', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, bagaimana kemudahan nelayan di lingkungan sekitar dalam memperoleh akses permodalan usaha serta menjual hasil tangkapan dengan harga yang relatif stabil dan wajar?', '{"1": "Sangat Sulit", "2": "Sulit", "3": "Cukup", "4": "Mudah", "5": "Sangat Mudah"}'::jsonb),
  ('Q_IND_08_masyarakat_pesisir', 'IND_08', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana masyarakat atau kelompok usaha di wilayah pesisir Cilegon mengembangkan produk olahan ikan, seperti makanan khas atau oleh-oleh, untuk meningkatkan nilai jual hasil perikanan?', '{"1": "Sangat Rendah", "2": "Rendah", "3": "Sedang", "4": "Tinggi", "5": "Sangat Tinggi"}'::jsonb),
  ('Q_IND_09_masyarakat_pesisir', 'IND_09', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, bagaimana tingkat kerukunan, solidaritas, dan kebersamaan warga di kampung pesisir dalam kegiatan gotong royong, kebersihan pantai, serta kegiatan sosial dan budaya setempat?', '{"1": "Sangat Rendah", "2": "Rendah", "3": "Sedang", "4": "Tinggi", "5": "Sangat Tinggi"}'::jsonb),
  ('Q_IND_10_masyarakat_pesisir', 'IND_10', 'masyarakat_pesisir', 'Menurut pengalaman atau pengamatan Bapak/Ibu, bagaimana penyelesaian perselisihan pemanfaatan ruang pesisir dan laut apabila terjadi konflik antara nelayan, pihak industri, atau pengelola wisata pesisir di Kota Cilegon?', '{"1": "Sangat Tidak Efektif", "2": "Tidak Efektif", "3": "Cukup Efektif", "4": "Efektif", "5": "Sangat Efektif"}'::jsonb),
  ('Q_IND_11_masyarakat_pesisir', 'IND_11', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana masyarakat pesisir, khususnya nelayan kecil, memiliki kesempatan yang adil untuk mengakses pantai dan sumber daya laut guna memenuhi kebutuhan hidup dan mencari nafkah?', '{"1": "Sangat Tidak Adil", "2": "Tidak Adil", "3": "Cukup Adil", "4": "Adil", "5": "Sangat Adil"}'::jsonb),
  ('Q_IND_12_masyarakat_pesisir', 'IND_12', 'masyarakat_pesisir', 'Menurut pandangan Bapak/Ibu, seberapa besar keyakinan bahwa mata pencaharian perikanan tangkap dan kehidupan komunitas nelayan di pesisir Cilegon dapat terus berlanjut serta menarik minat generasi muda dalam 10–20 tahun mendatang?', '{"1": "Sangat Tidak Yakin", "2": "Tidak Yakin", "3": "Cukup Yakin", "4": "Yakin", "5": "Sangat Yakin"}'::jsonb),
  ('Q_IND_13_masyarakat_pesisir', 'IND_13', 'masyarakat_pesisir', 'Menurut pengalaman Bapak/Ibu, seberapa jelas dan terbuka informasi mengenai kebijakan, program pemerintah, serta bantuan sektor perikanan disampaikan kepada masyarakat pesisir di Kota Cilegon?', '{"1": "Sangat Tidak Terbuka", "2": "Kurang Terbuka", "3": "Cukup Terbuka", "4": "Terbuka", "5": "Sangat Terbuka"}'::jsonb),
  ('Q_IND_14_masyarakat_pesisir', 'IND_14', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana masyarakat pesisir atau perwakilannya dilibatkan dalam musyawarah dan konsultasi sebelum pemerintah menetapkan kebijakan atau program pengelolaan wilayah pesisir dan perikanan di Kota Cilegon?', '{"1": "Tidak Pernah Dilibatkan", "2": "Jarang Dilibatkan", "3": "Kadang-kadang Dilibatkan", "4": "Sering Dilibatkan", "5": "Selalu Dilibatkan"}'::jsonb),
  ('Q_IND_15_masyarakat_pesisir', 'IND_15', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, bagaimana ketegasan aparat berwenang dalam mengawasi dan menindak pelanggaran aturan di wilayah pesisir dan perairan Cilegon, seperti pembuangan limbah ilegal atau kegiatan yang merusak lingkungan laut?', '{"1": "Sangat Tidak Tegas", "2": "Kurang Tegas", "3": "Cukup Tegas", "4": "Tegas", "5": "Sangat Tegas dan Konsisten"}'::jsonb),
  ('Q_IND_16_masyarakat_pesisir', 'IND_16', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, seberapa baik koordinasi antara pemerintah daerah, kelurahan, dinas terkait, aparat berwenang, dan pihak industri dalam menangani permasalahan lingkungan serta pengelolaan wilayah pesisir Cilegon?', '{"1": "Sangat Buruk", "2": "Buruk", "3": "Cukup", "4": "Baik", "5": "Sangat Baik"}'::jsonb),
  ('Q_IND_17_masyarakat_pesisir', 'IND_17', 'masyarakat_pesisir', 'Menurut Bapak/Ibu, sejauh mana kebijakan pengelolaan wilayah pesisir Cilegon telah mempertimbangkan secara adil dan seimbang kepentingan masyarakat pesisir, nelayan, pelaku usaha, dan sektor industri?', '{"1": "Sangat Tidak Terpadu", "2": "Kurang Terpadu", "3": "Cukup Terpadu", "4": "Terpadu", "5": "Sangat Terpadu"}'::jsonb),
  ('Q_IND_18_masyarakat_pesisir', 'IND_18', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, seberapa konsisten dan berkesinambungan program penataan wilayah pesisir, pemberdayaan masyarakat, serta pengelolaan perikanan tangkap di Kota Cilegon dilaksanakan dari tahun ke tahun?', '{"1": "Sangat Tidak Konsisten", "2": "Tidak Konsisten", "3": "Cukup Konsisten", "4": "Konsisten", "5": "Sangat Konsisten dan Terarah"}'::jsonb),
  ('Q_IND_19_masyarakat_pesisir', 'IND_19', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana pemerintah menggunakan data kondisi nelayan, kebutuhan masyarakat pesisir, serta hasil pendataan atau kajian lapangan sebagai dasar penyusunan kebijakan dan program perikanan di Kota Cilegon?', '{"1": "Sangat Tidak Memadai", "2": "Kurang Memadai", "3": "Cukup Memadai", "4": "Memadai", "5": "Sangat Memadai"}'::jsonb),
  ('Q_IND_24_masyarakat_pesisir', 'IND_24', 'masyarakat_pesisir', 'Sejauh mana Bapak/Ibu menerima dan menyetujui peraturan pemerintah terkait pengelolaan perikanan tangkap dan penataan wilayah pesisir di Kota Cilegon?', '{"1": "Sangat Tidak Setuju", "2": "Tidak Setuju", "3": "Netral atau Ragu-ragu", "4": "Setuju", "5": "Sangat Setuju"}'::jsonb),
  ('Q_IND_25_masyarakat_pesisir', 'IND_25', 'masyarakat_pesisir', 'Sejauh mana Bapak/Ibu setuju bahwa sumber daya ikan dan lingkungan laut pesisir Cilegon perlu dijaga secara berkelanjutan agar tetap mendukung mata pencaharian nelayan dan kebutuhan generasi mendatang?', '{"1": "Sangat Tidak Setuju", "2": "Tidak Setuju", "3": "Netral atau Ragu-ragu", "4": "Setuju", "5": "Sangat Setuju"}'::jsonb),
  ('Q_IND_26_masyarakat_pesisir', 'IND_26', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, sejauh mana nelayan di lingkungan pesisir Cilegon mematuhi ketentuan wilayah penangkapan ikan, perizinan, dan penggunaan alat tangkap yang diperbolehkan?', '{"1": "Sangat Tidak Patuh", "2": "Kurang Patuh", "3": "Cukup Patuh", "4": "Patuh", "5": "Sangat Patuh"}'::jsonb),
