  ('Q_IND_31_masyarakat_pesisir', 'IND_31', 'masyarakat_pesisir', 'Dalam 12 bulan terakhir, seberapa sering Bapak/Ibu menyampaikan aspirasi, usulan, atau pengaduan mengenai permasalahan lingkungan dan kebutuhan masyarakat pesisir kepada pemerintah kelurahan, dinas terkait, atau pihak berwenang lainnya?', '{"1": "Tidak Pernah", "2": "Jarang", "3": "Kadang-kadang", "4": "Sering", "5": "Sangat Sering"}'::jsonb),
