  ('Q_IND_21_masyarakat_pesisir', 'IND_21', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, seberapa efektif kelompok nelayan atau organisasi masyarakat pesisir, seperti KUB, Rukun Nelayan, atau koperasi, dalam mengadakan kegiatan bersama, membina anggota, dan membantu menyelesaikan permasalahan masyarakat?', '{"1": "Sangat Tidak Efektif", "2": "Tidak Efektif", "3": "Cukup Efektif", "4": "Efektif", "5": "Sangat Efektif"}'::jsonb),
