  ('Q_IND_34_masyarakat_pesisir', 'IND_34', 'masyarakat_pesisir', 'Menurut pengamatan Bapak/Ibu, seberapa besar aktivitas ekonomi masyarakat di lingkungan pesisir, seperti warung, usaha penyewaan tempat tinggal, perdagangan, dan jasa, bergantung pada kegiatan serta hasil tangkapan nelayan?', '{"1": "Sangat Rendah", "2": "Rendah", "3": "Sedang", "4": "Tinggi", "5": "Sangat Tinggi"}'::jsonb),
  ('Q_IND_35_masyarakat_pesisir', 'IND_35', 'masyarakat_pesisir', 'Menurut Bapak/Ibu, seberapa penting pelestarian tradisi, kebersamaan, dan identitas budaya masyarakat kampung nelayan untuk menjaga keberlanjutan komunitas pesisir Cilegon?', '{"1": "Sangat Tidak Penting", "2": "Tidak Penting", "3": "Cukup Penting", "4": "Penting", "5": "Sangat Penting"}'::jsonb),
